import '@tensorflow/tfjs'
import '@tensorflow/tfjs-backend-webgl'
import {
  SpeechCommandRecognizer,
  create
} from '@tensorflow-models/speech-commands'

export enum COMMAND {
  BUZZIN_COMMAND = 'go',
  BUZZOUT_COMMAND = 'stop'
}

export interface speechCommand {
  command: COMMAND
  callback: () => void
}

class ASREngine {
  _recognizer: SpeechCommandRecognizer
  _init: boolean
  _buzzedin: boolean
  _commands: { [key: string]: speechCommand['callback'] }
  _last_command: string
  _threshold: number
  constructor(commands?: Array<speechCommand>, threshold?: number) {
    this._recognizer = create('BROWSER_FFT')
    this._init = false
    this._commands = {}
    ;(commands || []).forEach((element) => {
      this._commands[element.command] = element.callback
    })
    this._last_command = ''
    this._threshold = threshold || 0.9
    this._buzzedin = false
  }

  intialize = async () => {
    await this._recognizer.ensureModelLoaded()
    console.log(this._recognizer.wordLabels())
    this._init = true
  }

  argMax = (array: Float32Array) => {
    var largest = 0
    var largest_index = -1
    for (let index = 0; index < array.length; index++) {
      if (array[index] > largest) {
        largest = array[index]
        largest_index = index
      }
    }
    return largest_index
  }

  update = (commands: Array<speechCommand>) => {
    commands.forEach((element) => {
      this._commands[element.command] = element.callback
    })
  }

  listen = () => {
    try {
      this._listen()
    } catch (error) {
      console.debug(error)
    }
  }

  restart = () => {
    this._recognizer
      .stopListening()
      .then(() => {
        this._listen()
      })
      .catch((error) => {
        console.debug(error)
      })
  }

  _listen = () => {
    this._recognizer
      .ensureModelLoaded()
      .then(() => {
        this._recognizer.listen(
          (result) => {
            const word = this._recognizer.wordLabels()[
              this.argMax(result.scores as Float32Array)
            ] as COMMAND

            if (word == COMMAND.BUZZIN_COMMAND && this._buzzedin) {
              return Promise.resolve()
            } else if (word == COMMAND.BUZZOUT_COMMAND && !this._buzzedin) {
              return Promise.resolve()
            } else if (word == COMMAND.BUZZIN_COMMAND && !this._buzzedin) {
              this._buzzedin = true
            } else if (word == COMMAND.BUZZOUT_COMMAND && !this._buzzedin) {
              this._buzzedin = false
            }

            return new Promise<void>((resolve, reject) => {
              if (this._last_command != word) {
                this._last_command = word
                try {
                  if (word in this._commands) {
                    this._commands[word]()
                    resolve()
                  }
                } catch (error) {
                  reject()
                }
              }
              resolve()
            })
          },
          {
            includeSpectrogram: true,
            probabilityThreshold: this._threshold
          }
        )
      })
      .catch(console.debug)
  }

  stop = async () => {
    if (this._recognizer.isListening()) return this._recognizer.stopListening()
  }
}

export default ASREngine
